@prefix ada: <https://ada.astromat.org/metadata/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a ada:PSFDTabular ;
                    ada:imageName "crater_overview_001.tif",
                        "crater_overview_002.tif" ;
                    ada:imageViewingConditions "nadir, 50m altitude" ] ;
            sh:resultMessage "PSFD detail nodes must declare ada:componentType." ;
            sh:resultPath ada:componentType ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:string ;
                    sh:maxCount 1 ;
                    sh:message "PSFD detail nodes must declare ada:componentType." ;
                    sh:minCount 1 ;
                    sh:path ada:componentType ] ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms true .
